#!/usr/bin/env node
// Generates the Swift model layer of the iOS app from the contract schema (the same source of truth as DOMAIN.md and types.ts).
//
//   node scripts/gen-ios-models.mjs            write apps/ios/Flowd/Core/Models/{Enums,Entities}*.swift and
//                                              apps/ios/FlowdTests/FormulaVectorsData.swift
//   node scripts/gen-ios-models.mjs --check    exit 1 when any generated file is stale (CI)
//
// There is no Swift compiler on the dev machines, so the models are generated, not typed: every enum value, field name and type comes
// from packages/contract/schema/*.mjs, and scripts/check-ios-models.mjs then compares the generated Swift against the real fixture JSON.
// Rules (apps/ios/STRUCTURE.md, DOMAIN.md section 2):
//   - models are `struct ... : Codable, Hashable, Identifiable (when they have an id), Sendable`; no CodingKeys (the app decodes with
//     `.convertFromSnakeCase`, see Core/Utilities/FlowdJSON.swift);
//   - every enum has `case unknown` and a tolerant decoder, so a value added to the contract tomorrow never crashes decoding;
//   - `iso` fields are `Date`, `date` fields stay `String` ("YYYY-MM-DD"), money is `Int` cents, ratios are `Double`.
// Hand-written helpers live in Core/Models/Primitives.swift, ModelExtensions.swift and ReadModels.swift.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { pathToFileURL } from "node:url";
import { camelFromSnake, caseName, FRAMEWORK_SYMBOLS, ident, swiftTypeName } from "./lib/ios-names.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const checkOnly = process.argv.includes("--check");
const schemaUrl = pathToFileURL(path.join(root, "packages/contract/schema/index.mjs")).href;
const S = await import(schemaUrl);
const { ENUMS, VALUE_TYPES, ENTITIES } = S;
const parseType = (await import(pathToFileURL(path.join(root, "packages/contract/schema/dsl.mjs")).href)).parseType;

const outDir = path.join(root, "apps/ios/Flowd/Core/Models");
const testsDir = path.join(root, "apps/ios/FlowdTests");
const engineDir = path.join(root, "apps/ios/Flowd/Core/Engine");

const HEADER =
  "// GENERATED by scripts/gen-ios-models.mjs from packages/contract/schema/*.mjs. Do not edit by hand: change the schema, then run  node scripts/gen-ios-models.mjs\n" +
  "// Names, enum values and field types mirror packages/contract/DOMAIN.md sections 5 to 7. Decoded with .convertFromSnakeCase.\n";

// ── helpers ──────────────────────────────────────────────────────────────────────────────────────
const errors = [];
const strLit = (s) => `"${String(s).replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\r?\n/g, " ")}"`;
const docLines = (text, indent = "") =>
  String(text ?? "")
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter((l) => l.length > 0)
    .map((l) => `${indent}/// ${l}`)
    .join("\n");

const enumNames = new Set(ENUMS.map((e) => e.name));
const valueNames = new Set(VALUE_TYPES.map((v) => v.name));
const entityNames = new Set(ENTITIES.map((e) => e.name));

for (const n of [...enumNames, ...valueNames, ...entityNames]) {
  const sw = swiftTypeName(n);
  if (FRAMEWORK_SYMBOLS.has(sw)) errors.push(`type name ${n} -> ${sw} collides with a framework symbol; add it to TYPE_RENAMES`);
}

/** Swift type of a parsed contract type. */
function swiftType(p) {
  let base;
  switch (p.kind) {
    case "id":
    case "ref":
      base = "String";
      break;
    case "art":
      base = "ArtSeed";
      break;
    case "enum":
      base = swiftTypeName(p.name);
      break;
    case "obj":
      base = swiftTypeName(p.name);
      break;
    case "map":
      base = `[String: ${swiftType({ ...p.inner, array: false })}]`;
      break;
    case "prim":
      switch (p.name) {
        case "string":
        case "text":
        case "hex":
        case "url":
        case "date":
          base = "String";
          break;
        case "int":
        case "cents":
          base = "Int";
          break;
        case "number":
        case "ratio":
        case "pct":
          base = "Double";
          break;
        case "bool":
          base = "Bool";
          break;
        case "iso":
          base = "Date";
          break;
        default:
          errors.push(`unsupported primitive ${p.name}`);
          base = "String";
      }
      break;
    default:
      errors.push(`unsupported type kind ${p.kind}`);
      base = "String";
  }
  return p.array ? `[${base}]` : base;
}

const fieldSwiftType = (f) => {
  const p = parseType(f.type);
  const t = swiftType(p);
  return f.required ? t : `${t}?`;
};

// ── enums ────────────────────────────────────────────────────────────────────────────────────────
const RESERVED_MEMBERS = new Set(["label", "tone", "meaning", "rawValue", "allCases", "hashValue", "unknown", "isKnown", "init", "self", "description", "hash"]);

function genEnum(en) {
  const name = swiftTypeName(en.name);
  const cases = en.values.map((v) => ({ ...v, swift: caseName(en.name, v.value) }));
  const seen = new Set();
  for (const c of cases) {
    if (seen.has(c.swift)) errors.push(`enum ${en.name}: duplicate Swift case ${c.swift}`);
    seen.add(c.swift);
    const bare = c.swift.replace(/`/g, "");
    if (RESERVED_MEMBERS.has(bare)) errors.push(`enum ${en.name}: case ${bare} collides with a generated member`);
  }
  const lines = [];
  lines.push(`// MARK: - ${en.name}`);
  lines.push("");
  lines.push(docLines(en.doc));
  lines.push(`enum ${name}: String, Codable, Hashable, Sendable, CaseIterable {`);
  for (const c of cases) lines.push(`    case ${c.swift} = ${strLit(c.value)}`);
  lines.push("    /// A value this build does not know yet (decoded from JSON, never sent).");
  lines.push('    case unknown = "unknown"');
  lines.push("");
  lines.push(`    /// Every value the contract defines (without \`.unknown\`), in contract order.`);
  lines.push(`    static var allCases: [${name}] {`);
  lines.push(`        return [${cases.map((c) => "." + c.swift).join(", ")}]`);
  lines.push("    }");
  lines.push("");
  lines.push("    init(from decoder: Decoder) throws {");
  lines.push("        let container: SingleValueDecodingContainer = try decoder.singleValueContainer()");
  lines.push("        let raw: String = try container.decode(String.self)");
  lines.push(`        self = ${name}(rawValue: raw) ?? .unknown`);
  lines.push("    }");
  lines.push("");
  lines.push("    func encode(to encoder: Encoder) throws {");
  lines.push("        var container: SingleValueEncodingContainer = encoder.singleValueContainer()");
  lines.push("        try container.encode(rawValue)");
  lines.push("    }");
  lines.push("");
  lines.push("    /// False for `.unknown`.");
  lines.push("    var isKnown: Bool {");
  lines.push("        return self != .unknown");
  lines.push("    }");
  lines.push("");
  lines.push("    /// UI label from the contract (\"Views still counting\").");
  lines.push("    var label: String {");
  lines.push("        switch self {");
  for (const c of cases) lines.push(`        case .${c.swift}: return ${strLit(c.label)}`);
  lines.push('        case .unknown: return "Unknown"');
  lines.push("        }");
  lines.push("    }");
  lines.push("");
  lines.push("    /// Colour tone from the contract; map to a design-system tone with `.flowdTone`.");
  lines.push("    var tone: ContractTone {");
  lines.push("        switch self {");
  for (const c of cases) lines.push(`        case .${c.swift}: return .${c.tone}`);
  lines.push("        case .unknown: return .neutral");
  lines.push("        }");
  lines.push("    }");
  lines.push("");
  lines.push("    /// Plain-English meaning from the contract, when it has one.");
  lines.push("    var meaning: String? {");
  lines.push("        switch self {");
  for (const c of cases) {
    if (c.meaning && String(c.meaning).trim().length > 0) lines.push(`        case .${c.swift}: return ${strLit(c.meaning)}`);
  }
  const withMeaning = cases.filter((c) => c.meaning && String(c.meaning).trim().length > 0).length;
  if (withMeaning < cases.length) lines.push("        default: return nil");
  else lines.push("        case .unknown: return nil");
  lines.push("        }");
  lines.push("    }");
  lines.push("}");
  lines.push("");
  return lines.join("\n");
}

// ── structs ──────────────────────────────────────────────────────────────────────────────────────
function genStruct(def, kind) {
  const name = swiftTypeName(def.name);
  const hasId = def.fields.some((f) => f.name === "id");
  const key = kind === "entity" && !hasId && Array.isArray(def.key) ? def.key : null;
  const conf = ["Codable", "Hashable"];
  if (hasId || key) conf.push("Identifiable");
  conf.push("Sendable");
  const lines = [];
  lines.push(`// MARK: - ${def.name}${kind === "entity" ? ` (${def.table})` : ""}`);
  lines.push("");
  lines.push(docLines(def.doc));
  lines.push(`struct ${name}: ${conf.join(", ")} {`);
  const props = new Set();
  for (const f of def.fields) {
    const prop = camelFromSnake(f.name);
    if (props.has(prop)) errors.push(`${def.name}: duplicate property ${prop}`);
    props.add(prop);
    const d = docLines(f.doc, "    ");
    if (d) lines.push(d);
    lines.push(`    var ${ident(prop)}: ${fieldSwiftType(f)}`);
  }
  if (key) {
    const parts = key.map((k) => {
      const f = def.fields.find((x) => x.name === k);
      if (!f) {
        errors.push(`${def.name}: key field ${k} missing`);
        return '""';
      }
      const p = parseType(f.type);
      const prop = camelFromSnake(k);
      if (p.kind === "prim" && p.name === "iso") return `String(Int(${prop}.timeIntervalSince1970))`;
      return prop;
    });
    lines.push("");
    lines.push(`    /// Composite identity (${key.join(" + ")}).`);
    lines.push("    var id: String {");
    lines.push(`        return [${parts.join(", ")}].joined(separator: "|")`);
    lines.push("    }");
  }
  lines.push("}");
  lines.push("");
  return lines.join("\n");
}

// ── assign value types to the file of the first entity that references them ───────────────────────
const valueByName = new Map(VALUE_TYPES.map((v) => [v.name, v]));
const groupOfValue = new Map();
function visitValue(vname, group) {
  if (groupOfValue.has(vname)) return;
  groupOfValue.set(vname, group);
  const v = valueByName.get(vname);
  for (const f of v.fields) visitType(parseType(f.type), group);
}
function visitType(p, group) {
  if (p.kind === "obj") visitValue(p.name, group);
  if (p.kind === "map") visitType(p.inner, group);
}
for (const e of ENTITIES) for (const f of e.fields) visitType(parseType(f.type), e.group);
for (const v of VALUE_TYPES) if (!groupOfValue.has(v.name)) groupOfValue.set(v.name, "Misc");

// ── assemble files ───────────────────────────────────────────────────────────────────────────────
const files = new Map();
const put = (file, text) => files.set(file, (files.get(file) ?? "") + text);

const enumGroups = [...new Set(ENUMS.map((e) => e.group))];
for (const g of enumGroups) {
  const list = ENUMS.filter((e) => e.group === g);
  const file = `Enums${g}.swift`;
  put(file, `${HEADER}\nimport Foundation\n\n// Enumerations: ${g} (${list.length}). Every enum decodes unknown values to \`.unknown\`.\n\n`);
  for (const e of list) put(file, genEnum(e) + "\n");
}

const entityGroups = [...new Set(ENTITIES.map((e) => e.group))];
for (const g of entityGroups) {
  const ents = ENTITIES.filter((e) => e.group === g);
  const vals = VALUE_TYPES.filter((v) => groupOfValue.get(v.name) === g);
  const file = `Entities${g}.swift`;
  put(file, `${HEADER}\nimport Foundation\n\n// Entities (one per fixture file) and their nested value types: ${g}.\n\n`);
  for (const e of ents) put(file, genStruct(e, "entity") + "\n");
  if (vals.length > 0) put(file, `// MARK: - Value types used by ${g} entities\n\n`);
  for (const v of vals) put(file, genStruct(v, "value") + "\n");
}
{
  const vals = VALUE_TYPES.filter((v) => groupOfValue.get(v.name) === "Misc");
  if (vals.length > 0) {
    const file = "EntitiesMisc.swift";
    put(file, `${HEADER}\nimport Foundation\n\n`);
    for (const v of vals) put(file, genStruct(v, "value") + "\n");
  }
}

// ── constants (FlowdConstants) ───────────────────────────────────────────────────────────────────
// Every number the app needs from packages/contract/schema/constants.mjs, as nested enums of static lets. Names are the camelCased keys, so
// `CONSTANTS.fees.instant_payout_rate` is `FlowdConstants.Fees.instantPayoutRate`. Hand-written accessors (by Tier, Plan, ...) live in
// Core/Engine/ConstantsAccessors.swift; nothing else may hard-code a rate, threshold or window.
{
  const C = S.CONSTANTS;
  const SKIP = new Set(["now", "lint.rules", "launch_targets"]);
  const RENAME_NESTED = { world: "WorldInfo", daily_drop: "DailyDropRules" };
  const pascal = (n) => n.charAt(0).toUpperCase() + n.slice(1);
  const isDoubleKey = (key, pathStr) =>
    /(^|_)(rate|ratio|multiplier)(_|$)/.test(key) || /(^|\.)(weights|band_view_multiplier|views_quantile_ratio|conversion_band_ratio)(\.|$)/.test(pathStr);
  const num = (v, asDouble) => {
    if (asDouble || !Number.isInteger(v)) {
      const t = String(v);
      return /[.eE]/.test(t) ? t : t + ".0";
    }
    const neg = v < 0 ? "-" : "";
    const digits = String(Math.abs(v));
    return neg + (digits.length > 4 ? digits.replace(/\B(?=(\d{3})+(?!\d))/g, "_") : digits);
  };
  const out = [];
  out.push(HEADER + "// Every number the contract defines (packages/contract/schema/constants.mjs, mirrored in docs/DECISIONS.md).");
  out.push("import Foundation");
  out.push("");
  out.push("/// One line of a Hook Score or Flow Score checklist: full, half or zero points by its rule.");
  out.push("struct ChecklistSpec: Hashable, Sendable {");
  out.push("    let id: String");
  out.push("    let label: String");
  out.push("    let weight: Int");
  out.push("    let rule: String");
  out.push("}");
  out.push("");
  out.push("/// The contract's CONSTANTS. Names are the camelCased keys: fees.instant_payout_rate -> FlowdConstants.Fees.instantPayoutRate.");
  out.push("enum FlowdConstants {");
  const emit = (obj, depth, pathStr) => {
    const pad = "    ".repeat(depth);
    for (const [key, value] of Object.entries(obj)) {
      const p = pathStr ? pathStr + "." + key : key;
      if (SKIP.has(p)) continue;
      const name = camelFromSnake(key.toLowerCase());
      if (typeof value === "string") out.push(pad + "static let " + ident(name) + ": String = " + strLit(value));
      else if (typeof value === "boolean") out.push(pad + "static let " + ident(name) + ": Bool = " + value);
      else if (typeof value === "number") {
        const d = isDoubleKey(key, p);
        out.push(pad + "static let " + ident(name) + ": " + (d || !Number.isInteger(value) ? "Double" : "Int") + " = " + num(value, d));
      } else if (Array.isArray(value)) {
        if (value.length > 0 && typeof value[0] === "object" && value[0] !== null) {
          if (p === "scores.hook_checklist" || p === "scores.flow_checklist") {
            out.push(pad + "static let " + ident(name) + ": [ChecklistSpec] = [");
            for (const it of value) out.push(pad + "    ChecklistSpec(id: " + strLit(it.id) + ", label: " + strLit(it.label) + ", weight: " + it.weight + ", rule: " + strLit(it.rule) + "),");
            out.push(pad + "]");
          } else errors.push("constants: unsupported array of objects at " + p);
        } else if (value.length === 0) errors.push("constants: empty array at " + p);
        else if (typeof value[0] === "string") out.push(pad + "static let " + ident(name) + ": [String] = [" + value.map(strLit).join(", ") + "]");
        else {
          const dbl = value.some((v) => !Number.isInteger(v)) || isDoubleKey(key, p);
          out.push(pad + "static let " + ident(name) + ": [" + (dbl ? "Double" : "Int") + "] = [" + value.map((v) => num(v, dbl)).join(", ") + "]");
        }
      } else if (value && typeof value === "object") {
        const typeName = depth === 1 && RENAME_NESTED[key] ? RENAME_NESTED[key] : pascal(name);
        if (!out[out.length - 1].endsWith("{")) out.push("");
        out.push(pad + "enum " + typeName + " {");
        emit(value, depth + 1, p);
        out.push(pad + "}");
      } else errors.push("constants: unsupported value at " + p);
    }
  };
  emit(C, 1, "");
  out.push("}");
  files.set("__engine__/Constants.swift", out.join("\n").replace(/\n\n\}/g, "\n}") + "\n");
}

// ── fixture registry for the XCTest decoding suite ───────────────────────────────────────────────
// One entry per fixture file: the table name, the Swift row type and how to decode it, so `FixtureDecodingTests` proves every bundled fixture decodes
// with the app's own JSON rules (the same check scripts/check-ios-models.mjs does without a compiler).
{
  const lines = [];
  lines.push("// GENERATED by scripts/gen-ios-models.mjs from packages/contract/schema/*.mjs. Do not edit by hand.");
  lines.push("// One decoder per fixture table: FixtureDecodingTests decodes every bundled fixture through these.");
  lines.push("import Foundation");
  lines.push("@testable import Flowd");
  lines.push("");
  lines.push("enum FixtureRegistry {");
  lines.push("    /// The rows (or 1 for an object-shaped file) a fixture decodes to, or the decoding error.");
  lines.push("    typealias Decoder = (FixtureLoader) throws -> Int");
  lines.push("");
  lines.push("    static let decoders: [(table: String, decode: Decoder)] = [");
  const sorted = [...ENTITIES].sort((a, b) => a.table.localeCompare(b.table));
  sorted.forEach((e, i) => {
    const type = swiftTypeName(e.name);
    const sep = i === sorted.length - 1 ? "" : ",";
    if (e.shape === "object") lines.push(`        (table: "${e.table}", decode: { (loader: FixtureLoader) throws -> Int in _ = try loader.load(${type}.self, named: "${e.table}"); return 1 })${sep}`);
    else lines.push(`        (table: "${e.table}", decode: { (loader: FixtureLoader) throws -> Int in return try loader.load([${type}].self, named: "${e.table}").count })${sep}`);
  });
  lines.push("    ]");
  lines.push("}");
  files.set("__tests__/FixtureRegistry.swift", lines.join("\n") + "\n");
}

// ── formula vectors for the XCTest parity suite ──────────────────────────────────────────────────
{
  const vectorsPath = path.join(root, "packages/contract/formula-vectors.json");
  if (fs.existsSync(vectorsPath)) {
    const json = JSON.stringify(JSON.parse(fs.readFileSync(vectorsPath, "utf8")));
    if (json.includes('"""')) errors.push("formula vectors contain a triple quote");
    const text =
      `// GENERATED by scripts/gen-ios-models.mjs from packages/contract/formula-vectors.json. Do not edit by hand.\n` +
      `// The reference outputs of schema/formulas.mjs; EngineParityTests replays every case against Core/Engine.\n` +
      `import Foundation\n\nenum FormulaVectorsData {\n    static let json: String = #"""\n${json}\n"""#\n}\n`;
    files.set("__tests__/FormulaVectorsData.swift", text);
  }
}

if (errors.length > 0) {
  console.error("gen-ios-models: refused:\n  - " + errors.join("\n  - "));
  process.exit(1);
}

// ── write / check ────────────────────────────────────────────────────────────────────────────────
let changed = 0;
let same = 0;
for (const [file, text] of files) {
  const dest = file.startsWith("__tests__/")
    ? path.join(testsDir, file.slice("__tests__/".length))
    : file.startsWith("__engine__/")
      ? path.join(engineDir, file.slice("__engine__/".length))
      : path.join(outDir, file);
  const body = text.replace(/\n{3,}/g, "\n\n").replace(/\s+$/, "") + "\n";
  const existing = fs.existsSync(dest) ? fs.readFileSync(dest, "utf8") : null;
  if (existing === body) {
    same += 1;
    continue;
  }
  changed += 1;
  if (checkOnly) {
    console.log(`  ! stale: ${path.relative(root, dest)}`);
    continue;
  }
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, body);
  console.log(`  + ${path.relative(root, dest)}`);
}
console.log(`gen-ios-models: ${ENUMS.length} enums, ${VALUE_TYPES.length} value types, ${ENTITIES.length} entities -> ${files.size} files (${changed} ${checkOnly ? "stale" : "written"}, ${same} unchanged)`);
if (checkOnly && changed > 0) process.exit(1);
